namespace ChaosInterface
{
	float Chaos_Collision_MarginFraction = -1.0f;
	FAutoConsoleVariableRef CVarChaosCollisionMarginFraction(TEXT("p.Chaos.Collision.MarginFraction"), Chaos_Collision_MarginFraction, TEXT("Override the collision margin fraction set in Physics Settings (if >= 0)"));

	float Chaos_Collision_MarginMax = -1.0f;
	FAutoConsoleVariableRef CVarChaosCollisionMarginMax(TEXT("p.Chaos.Collision.MarginMax"), Chaos_Collision_MarginMax, TEXT("Override the max collision margin set in Physics Settings (if >= 0)"));

	CollisionTraceType = UPhysicsSettings::Get()->DefaultShapeComplexity;
}

const FChaosSolverConfiguration& SolverOptions = UPhysicsSettingsCore::Get()->SolverOptions;
float CollisionMarginFraction = FMath::Max(0.0f, SolverOptions.CollisionMarginFraction);
float CollisionMarginMax = FMath::Max(0.0f, SolverOptions.CollisionMarginMax);

// Test margins without changing physics settings
if (Chaos_Collision_MarginFraction >= 0.0f)
{
	CollisionMarginFraction = Chaos_Collision_MarginFraction;
}
if (Chaos_Collision_MarginMax >= 0.0f)
{
	CollisionMarginMax = Chaos_Collision_MarginMax;
}

for (const FKBoxElem& BoxElem : InParams.Geometry->BoxElems)
{
	const FKBoxElem ScaledBoxElem = BoxElem.GetFinalScaled(Scale, InParams.LocalTransform);
	const FTransform& BoxTransform = ScaledBoxElem.GetTransform();
	Chaos::FVec3 HalfExtents = Chaos::FVec3(ScaledBoxElem.X * 0.5f, ScaledBoxElem.Y * 0.5f, ScaledBoxElem.Z * 0.5f);

	HalfExtents.X = FMath::Max(HalfExtents.X, UE_KINDA_SMALL_NUMBER);
	HalfExtents.Y = FMath::Max(HalfExtents.Y, UE_KINDA_SMALL_NUMBER);
	HalfExtents.Z = FMath::Max(HalfExtents.Z, UE_KINDA_SMALL_NUMBER);

	const Chaos::FReal CollisionMargin = FMath::Min(2.0f * HalfExtents.GetMin() * CollisionMarginFraction, CollisionMarginMax);

	// AABB can handle translations internally but if we have a rotation we need to wrap it in a transform
	Chaos::FImplicitObjectPtr Implicit;
	if (!BoxTransform.GetRotation().IsIdentity())
	{
		auto ImplicitBox = MakeImplicitObjectPtr<Chaos::TBox<Chaos::FReal, 3>>(-HalfExtents, HalfExtents, CollisionMargin);
		Implicit = MakeImplicitObjectPtr<Chaos::TImplicitObjectTransformed<Chaos::FReal, 3>>(MoveTemp(ImplicitBox), BoxTransform);
	}
	else
	{
		Implicit = MakeImplicitObjectPtr<Chaos::TBox<Chaos::FReal, 3>>(BoxTransform.GetTranslation() - HalfExtents, BoxTransform.GetTranslation() + HalfExtents, CollisionMargin);

// The margin to use when we are colliding a convex shape against a zero-margin shape. E.g., Box-Triangle.
// When both shapes have a margin we use the minimum margin, but we don't want to use a zero margin because we hit the EPA degenerate case
// NOTE: This is currently disabled - margins for convex-trimesh cause bigger problems than the EPA issue
FRealSingle Chaos_Collision_ConvexZeroMargin = 0.0f;
FAutoConsoleVariableRef CVarChaos_Collision_ConvexZeroMargin(TEXT("p.Chaos.Collision.ConvexZeroMargin"), Chaos_Collision_ConvexZeroMargin, TEXT(""));

void FPBDCollisionConstraint::InitMarginsAndTolerances(const EImplicitObjectType ImplicitType0, const EImplicitObjectType ImplicitType1, const FRealSingle Margin0, const FRealSingle Margin1)
{
	// Set up the margins and tolerances to be used during the narrow phase.
	// When convex margins are enabled, at least one shape in a collision will always have a margin.
	// If convex margins are disabled, only quadratic shapes have a margin (their radius).
	// The collision tolerance is used for knowing whether a new contact matches an existing one.
	//
	// Margins: (Assuming convex margins are enabled...)
	// If a polygonal shape is not dynamic, its margin is zero.
	// Triangles always have zero margin (they are never dynamic anyway)
	// If we have two polygonal shapes, we use the smallest of the two margins unless one shape has zero margin.
	// If we have a quadratic shape versus a polygonal shape, we use a zero margin on the polygonal shape.
	// Note: If we have a triangle, it is always the second shape (currently we do not support triangle-triangle collision)
	//
	// CollisionTolerance:
	// For polygonal shapes the collision tolerance is proportional to the size of the smaller object. 
	// For quadratic shapes we want a collision tolerance much smaller than the radius.
	//
	const bool bIsQuadratic0 = ((ImplicitType0 == ImplicitObjectType::Sphere) || (ImplicitType0 == ImplicitObjectType::Capsule));
	const bool bIsQuadratic1 = ((ImplicitType1 == ImplicitObjectType::Sphere) || (ImplicitType1 == ImplicitObjectType::Capsule));

	// @todo(chaos): should probably be tunable. Used to use the same settings as the margin scale (for convex), but we want to support zero
	// margins, but still have a non-zero CollisionTolerance (it is used for matching contact points for friction and manifold reuse)
	const FRealSingle ToleranceScale = 0.1f;
	const FRealSingle QuadraticToleranceScale = 0.05f;

	if (!bIsQuadratic0 && !bIsQuadratic1)
	{
		// Only dynamic polytopes objects use margins
		const bool bIsDynamic0 = (GetParticle0() != nullptr) && (FConstGenericParticleHandle(GetParticle0())->IsDynamic());
		const bool bIsDynamic1 = (GetParticle1() != nullptr) && (FConstGenericParticleHandle(GetParticle1())->IsDynamic());
		const FRealSingle DynamicMargin0 = bIsDynamic0 ? FRealSingle(Margin0) : FRealSingle(0);
		const FRealSingle DynamicMargin1 = bIsDynamic1 ? FRealSingle(Margin1) : FRealSingle(0);

		const FRealSingle MaxSize0 = ((Implicit[0] != nullptr) && Implicit[0]->HasBoundingBox()) ? FRealSingle(Implicit[0]->BoundingBox().Extents().GetAbsMax()) : FRealSingle(0);
		const FRealSingle MaxSize1 = ((Implicit[1] != nullptr) && Implicit[1]->HasBoundingBox()) ? FRealSingle(Implicit[1]->BoundingBox().Extents().GetAbsMax()) : FRealSingle(0);
		const FRealSingle MaxSize = FMath::Min(MaxSize0, MaxSize1);
		CollisionTolerance = ToleranceScale * MaxSize;

		// If one shape has a zero margin, enforce a minimum margin to avoid the EPA degenerate case. E.g., Box-Triangle
		// If both shapes have a margin, use the smaller margin on both shapes. E.g., Box-Box
		// We should never see both shapes with zero margin, but if we did we'd end up with a zero margin
		const FRealSingle MinMargin = Chaos_Collision_ConvexZeroMargin;
		if (DynamicMargin0 == FRealSingle(0))
		{
			CollisionMargins[0] = 0;
			CollisionMargins[1] = FMath::Max(MinMargin, DynamicMargin1);
		}
		else if (DynamicMargin1 == FRealSingle(0))
		{
			CollisionMargins[0] = FMath::Max(MinMargin, DynamicMargin0);
			CollisionMargins[1] = 0;
		}
		else
		{
			CollisionMargins[0] = FMath::Min(DynamicMargin0, DynamicMargin1);
			CollisionMargins[1] = CollisionMargins[0];
		}

FORCEINLINE_DEBUGGABLE FVec3 SupportCore(const FVec3& Direction, const FReal InMargin, FReal* OutSupportDelta, int32& OutVertexIndex) const
{
	FVec3 ChosenPt;
	FIntVector ChosenAxis;
	for (int Axis = 0; Axis < d; ++Axis)
	{
		if(Direction[Axis] < 0)
		{
			ChosenPt[Axis] = MMin[Axis] + InMargin;
			ChosenAxis[Axis] = 0;
		}
		else
		{
			ChosenPt[Axis] = MMax[Axis] - InMargin;
			ChosenAxis[Axis] = 1;
		}
	}

	OutVertexIndex = GetIndex(ChosenAxis);

	// Maximum distance between the Core+Margin position and the original outer vertex
	constexpr FReal RootThreeMinusOne = FReal(1.7320508075688772935274463415059 - 1.0);
	if (OutSupportDelta != nullptr)
	{
		*OutSupportDelta = RootThreeMinusOne * InMargin;
	}

	return ChosenPt;
}

FContactPoint GJKContactPointMargin(const GeometryA& A, const GeometryB& B, const FRigidTransform3& BToATM, FReal MarginA, FReal MarginB, FGJKSimplexData& InOutGjkWarmStartData, FReal& OutMaxMarginDelta, int32& VertexIndexA, int32& VertexIndexB)
{
	SCOPE_CYCLE_COUNTER_MANIFOLD_GJK();

	FContactPoint Contact;

	FReal Penetration;
	FVec3 ClosestA, ClosestB, NormalA, NormalB;

	// GJK and EPA tolerances.
	// The GJK tolerance controls the separating distance at which GJK hands over to EPA. We need to be
	// able to normalize vectors of size epsilon with low error to avoid bad normals. 
	// This is a problem for floats with Epsilon < 1e-3f. For doubles it can be nmuch smaller although this
	// increases how many iterations we need when quadratic shapes are involved.
	// The EPA tolerance is used to determine whether a point projects inside a face on the simplezx.
	// EPA is also sensitive to the GJK tolerance, because it assumes the simplex from GJK contains the origin
	// but if it does not and the origin also does not project onto any simplex planes, we can end up with
	// a bad case in EPA where it rejects the correct face and returns some arbitrary other face. We need an
	// EPA Tolerance of about 1e-6 to avoid this in our test cases. It may need to be smaller.
	//const FReal Epsilon = 3.e-3f;	// original value for float implementation
	const FReal GJKEpsilon = Chaos_Collision_GJKEpsilon;
	const FReal EPAEpsilon = Chaos_Collision_EPAEpsilon;

	const TGJKCoreShape<GeometryA> AWithMargin(A, MarginA);
	const TGJKCoreShape<GeometryB> BWithMargin(B, MarginB);

	bool bHaveContact = false;
	if (bChaos_Collision_UseGJK2)
	{
		bHaveContact = GJKPenetrationWarmStartable2(AWithMargin, BWithMargin, BToATM, Penetration, ClosestA, ClosestB, NormalA, NormalB, VertexIndexA, VertexIndexB, InOutGjkWarmStartData, OutMaxMarginDelta, GJKEpsilon, EPAEpsilon);
	}
	else
	{
		bHaveContact = GJKPenetrationWarmStartable(AWithMargin, BWithMargin, BToATM, Penetration, ClosestA, ClosestB, NormalA, NormalB, VertexIndexA, VertexIndexB, InOutGjkWarmStartData, OutMaxMarginDelta, GJKEpsilon, EPAEpsilon);
	}

	if (bHaveContact)
	{
		Contact.ShapeContactPoints[0] = ClosestA;
		Contact.ShapeContactPoints[1] = ClosestB;
		Contact.ShapeContactNormal = -NormalB;	// We want normal pointing from B to A
		Contact.Phi = -Penetration;
	}

	return Contact;
}
